command_result.command:
cd /app; sed -i 's/#include <stdio.h>
#include <string.h>/&/; 0,/#include <stdio.h>/s//#include <stdio.h>
#include <stdlib.h>/' lib/core/strbuf.c; sed -i 's/^    case TOK_COMMA:$/    case TOK_COMMA:
    case TOK_END:/' lib/expr/parser.c; head -8 lib/core/strbuf.c; sed -n 76,86p lib/expr/parser.c; make -k -j8 2>&1 | grep -v '^gcc\|^sh \|^rm\|^ar' | head -60

cd /tmp && cat > t.c <<'EOF'
#include <qs/qs.h>
#include <stdio.h>
int main(void){double v; qs_eval("2^3",&v); printf("%g %s\n",v,QS_VERSION); return 0;}
EOF
gcc -I/tmp/stage/usr/include t.c /tmp/stage/usr/lib/libqs.a -lm -o t && ./t; cd /app; make -j8 >/dev/null; Q=build/bin/qcalc; for e in '-2^2' '2^3^2' '2^-1' '-2*3' '10-2-3' '7%4' '1/0' 'sqrt(-1)' '1e999' 'min(1)' 'abs(1,2)' 'foo(1)' '1 +' '(1' '2 $ 3' 'abcdefghijklmnopqrstuvwxyzabcdefg' 'clamp(5,1,3)' 'hypot(3,4)' '.5+.5' '' '3 4' 'min(1,)' '2^1000*2^1000' '1e308*10' '--3' '-(-3)' '0^-1' '-0' 'sqrt' '5 % 0'; do printf '%s => ' "$e"; $Q -e "$e"; echo "[$?]"; done; $Q --ops
